/**
 * PIXABAY'S RECORDED ANSWERS FOR THE BETA.267 COPPER HOLLOW FILM & PORTRAIT
 * GUIDED START (AGL-3942): host UGq7ta7ZKC, job gPcsOz5Djk, 2026-10-18
 * 19:44Z, a wedding and family photographer in Asheville "for couples
 * planning mountain weddings and elopements, and families … in the Blue
 * Ridge". What production's `stockPhotoSearches` cache held for the searches
 * its pages and its "Gallery collections" covers sent, read back by each
 * search's key, never searched again. Ids, sizes, page slugs and tags are
 * Pixabay's own, in its order; the contributor is left out, and one
 * contributor stands for all. Its `couple mountains` and `family mountains`
 * answers are the same cache entries the beta.265 recordings hold
 * (`ai-stock-photo-agl3856-beta265-recordings.ts`).
 */

const hit = (id: number, width: number, height: number, slug: string, tags: string): StockPhoto =>
  ({
    provider: 'pixabay',
    id: String(id),
    width,
    height,
    pageUrl: `https://pixabay.com/photos/${slug}/`,
    photographer: 'A Pixabay contributor',
    tags: tags ? tags.split(', ') : [],
    downloadUrl: `https://pixabay.com/get/g${id}_1280.jpg`,
  }) as StockPhoto

